SELECT id, conversation_id, sender_id, receiver_id, client_message_id, message_type, content, send_time FROM message WHERE conversation_id = #{conversationId}
AND id < #{beforeMessageId}
ORDER BY id DESC LIMIT #{limit}

SELECT COUNT(1)
FROM message
WHERE conversation_id = #{conversationId}
  AND receiver_id = #{userId}
  AND id > #{lastSyncMessageId}
